import{_ as n,C as r,c as l,o as s,ag as t,j as o,G as a}from"./chunks/framework.Bw-5EFTY.js";const p=JSON.parse('{"title":"Formidable Integration with FluentAffiliate","description":"","frontmatter":{},"headers":[],"relativePath":"guide/integrations/formidable-integration-with-fluentaffiliate.md","filePath":"guide/integrations/formidable-integration-with-fluentaffiliate.md","lastUpdated":1751458851000}'),f={name:"guide/integrations/formidable-integration-with-fluentaffiliate.md"};function g(u,e,d,m,h,c){const i=r("ZoomableImage");return s(),l("div",null,[e[0]||(e[0]=t('<h1 id="formidable-integration-with-fluentaffiliate" tabindex="-1">Formidable Integration with FluentAffiliate <a class="header-anchor" href="#formidable-integration-with-fluentaffiliate" aria-label="Permalink to &quot;Formidable Integration with FluentAffiliate&quot;">​</a></h1><p>Formidable is a powerful drag-and-drop form builder for WordPress. It makes creating forms quick and easy. Integrating Formidable with the FluentAffiliate plugin allows you to create affiliate registration forms, track subscriptions, and manage other payments without hassle.</p><p>In this guide, we’ll show you step by step how to connect Formidable Forms with FluentAffiliate.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Make sure both plugin Formidable and FluentAffiliate are installed and activated on your WordPress website.</p></div><h2 id="enable-formidable-in-fluentaffiliate" tabindex="-1">Enable Formidable in FluentAffiliate <a class="header-anchor" href="#enable-formidable-in-fluentaffiliate" aria-label="Permalink to &quot;Enable Formidable in FluentAffiliate&quot;">​</a></h2><ol><li>Once Formidable is active, go to the <strong>FluentAffiliate Dashboard</strong>.</li><li>From the top menu, click on <strong>Settings</strong>, and from the left sidebar, select the <strong>Integration Settings</strong> option.</li><li>ou will see a list of available integrations. Look for <strong>Formidable</strong> in this list. To enable the integration, click on the <strong>toggle</strong> button next to Formidable.</li></ol><p>Your <strong>Formidable</strong> integration with <strong>FluentAffiliate</strong> is now active, allowing you to create affiliate registration forms and track form submissions.</p><p>In the <strong>Manage</strong> section, you&#39;ll find additional settings to customize how the integration works.</p>',8)),o("p",null,[a(i,{src:"/guide/public/images/integrations/formidable/formidable-integration-setup.webp",alt:"Formidable Settings"})]),e[1]||(e[1]=t('<h2 id="configure-the-specific-form" tabindex="-1">Configure the Specific Form <a class="header-anchor" href="#configure-the-specific-form" aria-label="Permalink to &quot;Configure the Specific Form&quot;">​</a></h2><p>To configure a specific form with FluentAffiliate, you need to create a form in <strong>Formidable Forms</strong>.</p><ol><li>Once your form is ready, embed it on the desired page or post and save the form.</li><li>Next, <strong>copy</strong> the URL of the page or post where you have embedded the form. This <strong>URL</strong> will be used by your affiliates to generate their unique links.</li></ol>',3)),o("p",null,[a(i,{src:"/guide/public/images/integrations/formidable/configure-the-specific-form.webp",alt:"Formidable Form"})]),e[2]||(e[2]=t('<h2 id="generate-an-affiliate-link" tabindex="-1">Generate an Affiliate Link <a class="header-anchor" href="#generate-an-affiliate-link" aria-label="Permalink to &quot;Generate an Affiliate Link&quot;">​</a></h2><p>After you&#39;ve completed configuring the Formidable affiliate settings, the next step is to log in to your <strong>Affiliate</strong> area provided by FluentAffiliate. In the affiliate <strong>Links</strong> section, paste the <strong>URL</strong> of the form page you want to promote. FluentAffiliate will automatically generate a unique <strong>affiliate link</strong> for you.</p><p>Once your link is ready, <strong>copy</strong> the affiliate link and share it wherever you like — on social media, emails, blogs, or directly with your audience.</p>',3)),o("p",null,[a(i,{src:"/guide/public/images/integrations/formidable/affiliate-link-generation.webp",alt:"Affiliate Link Generation"})]),e[3]||(e[3]=t('<h3 id="troubleshooting-common-issues" tabindex="-1">Troubleshooting Common Issues <a class="header-anchor" href="#troubleshooting-common-issues" aria-label="Permalink to &quot;Troubleshooting Common Issues&quot;">​</a></h3><p>Here are solutions to common issues you might encounter:</p><ul><li><strong>Integration Toggle Not Visible:</strong> Ensure both Formidable and FluentAffiliate are activated. If the issue continues, deactivate and reactivate both plugins, and then check again.</li><li><strong>Form Not Tracking:</strong> Verify that the integration toggle is enabled. Also, you can test your affiliate link to ensure it working.</li><li><strong>Registration Form Not Working:</strong> Make sure the form is properly configured with the correct integration settings.</li></ul><p>And that&#39;s it. This is an easy process to integrate Formidable with FluentAffiliate.</p>',4))])}const _=n(f,[["render",g]]);export{p as __pageData,_ as default};
